import {Heading, Stack} from '@primer/react'
import {UnderlinePanels} from '@primer/react/experimental'
import {CodescanIcon, KeyIcon} from '@primer/octicons-react'
import {CampaignsCountsMetric} from '../components/CampaignsCountsMetric'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {SecurityCampaignsList} from '../components/SecurityCampaignsList'
import type {SecurityCampaignTemplate} from '../types/security-campaign-template'
import {useState, useMemo, useEffect} from 'react'
import {NoCampaignsBlankSlate} from '../components/NoCampaignsBlankSlate'
import {TemplateSelectionDialog} from '../components/TemplateSelectionDialog'
import {CampaignCreationButton} from '../components/CampaignCreationButton'
import {useCampaignsCountsQuery} from '../hooks/use-campaigns-counts-query'
import type {SecurityCampaignCounts} from '../types/security-campaign-counts'
import {CampaignFeedbackLink} from '../components/CampaignFeedbackLink'
import {getAlertTypeFromSearchParams, type AlertType} from '../types/security-campaign-alert'
import {updateSearchParams} from '@github-ui/history'

export interface OrgSecurityCampaignsIndexPayload {
  campaignCounts: SecurityCampaignCounts
  codeScanningCampaignCounts?: SecurityCampaignCounts
  secretScanningCampaignCounts?: SecurityCampaignCounts
  organizationLogin: string
  showFullView: boolean
  templates: SecurityCampaignTemplate[]
  codeScanningTemplates?: SecurityCampaignTemplate[]
  aboutCampaignsDocsUrl: string
  maxOpenCampaigns: number
  maxDraftCampaigns: number
  secretScanningTemplates?: SecurityCampaignTemplate[]
  codeScanningEnabled?: boolean
  secretProtectionEnabled?: boolean
}

export const OrgSecurityCampaignsIndex = () => {
  const {
    campaignCounts: initialCampaignCounts,
    codeScanningCampaignCounts,
    secretScanningCampaignCounts,
    showFullView,
    organizationLogin,
    templates,
    codeScanningTemplates = null,
    aboutCampaignsDocsUrl,
    maxOpenCampaigns,
    maxDraftCampaigns,
    secretScanningTemplates = null,
    codeScanningEnabled = false,
    secretProtectionEnabled = false,
  } = useRoutePayload<OrgSecurityCampaignsIndexPayload>()

  const [isTemplatesDialogOpen, setIsTemplatesDialogOpen] = useState(false)
  const [templateDialogType, setTemplateDialogType] = useState<AlertType | null>(null)

  // Initialize activeTab from URL parameter or default to 'code_scanning'
  const [activeTab, setActiveTab] = useState<AlertType>(() => {
    if (typeof window === 'undefined') {
      // Fallback for SSR or when window is not available
      return 'code_scanning'
    }
    const currentSearchParams = new URLSearchParams(window.location.search)
    return getAlertTypeFromSearchParams(currentSearchParams)
  })

  // Update URL when activeTab changes
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const currentSearchParams = new URLSearchParams(window.location.search)
      const alertTypeParam = getAlertTypeFromSearchParams(currentSearchParams)
      if (alertTypeParam !== activeTab) {
        const updatedParams = new URLSearchParams(currentSearchParams)
        updatedParams.set('alert_type', activeTab)
        updateSearchParams(updatedParams)
      }
    }
  }, [activeTab])

  const initialCodeCounts: SecurityCampaignCounts = useMemo(
    () => codeScanningCampaignCounts ?? initialCampaignCounts,
    [codeScanningCampaignCounts, initialCampaignCounts],
  )
  const initialSecretCounts: SecurityCampaignCounts = useMemo(
    () => secretScanningCampaignCounts ?? initialCampaignCounts,
    [secretScanningCampaignCounts, initialCampaignCounts],
  )

  const {data: codeCounts = initialCodeCounts} = useCampaignsCountsQuery(
    organizationLogin,
    initialCodeCounts,
    'code_scanning',
  )

  const {data: secretCounts = initialSecretCounts} = useCampaignsCountsQuery(
    organizationLogin,
    initialSecretCounts,
    'secret_scanning',
  )

  // Active counts depending on tab selection (or default single view)
  const counts: SecurityCampaignCounts = activeTab === 'code_scanning' ? codeCounts : secretCounts

  const {
    openCampaignsCount,
    openCampaignsTotalCount,
    openCampaignsOpenCount,
    openCampaignsInProgressCount,
    openCampaignsFixedCount,
    openCampaignsDismissedCount,
    closedCampaignsCount,
    closedCampaignsTotalCount,
    closedCampaignsOpenCount,
    closedCampaignsFixedCount,
    closedCampaignsDismissedCount,
    draftCampaignsCount,
    openCampaignsCountWithSpam,
    draftCampaignsCountWithSpam,
    hasOpenSpam,
    hasDraftSpam,
  } = counts

  const anyCampaigns = openCampaignsCount + closedCampaignsCount + draftCampaignsCount > 0
  const codeHasAny =
    codeCounts.openCampaignsCount + codeCounts.closedCampaignsCount + codeCounts.draftCampaignsCount > 0
  const secretHasAny =
    secretCounts.openCampaignsCount + secretCounts.closedCampaignsCount + secretCounts.draftCampaignsCount > 0

  const showCampaignCreationButton = showFullView && anyCampaigns
  const maxCampaignsReached =
    draftCampaignsCountWithSpam === maxDraftCampaigns && openCampaignsCountWithSpam === maxOpenCampaigns

  const CampaignsBody = (
    <>
      {showFullView && (
        <div className="d-flex flex-auto flex-column flex-md-row gap-2 pt-1">
          <CampaignsCountsMetric
            title="Open campaigns"
            description="Total alerts included in open campaigns."
            campaignsCount={openCampaignsCount}
            totalAlertCount={openCampaignsTotalCount}
            openAlertsCount={openCampaignsOpenCount - (openCampaignsInProgressCount ?? 0)}
            inProgressAlertsCount={openCampaignsInProgressCount ?? undefined}
            fixedAlertsCount={openCampaignsFixedCount}
            dismissedAlertsCount={openCampaignsDismissedCount}
          />
          <CampaignsCountsMetric
            title="Closed campaigns"
            description="Total alerts included in closed campaigns."
            campaignsCount={closedCampaignsCount}
            totalAlertCount={closedCampaignsTotalCount}
            openAlertsCount={closedCampaignsOpenCount}
            fixedAlertsCount={closedCampaignsFixedCount}
            dismissedAlertsCount={closedCampaignsDismissedCount}
          />
        </div>
      )}
      <div className="tmp-mt-3">
        <SecurityCampaignsList
          showFullView={showFullView}
          organizationLogin={organizationLogin}
          openCount={openCampaignsCount}
          closedCount={closedCampaignsCount}
          draftCount={draftCampaignsCount}
          maxOpenCampaigns={maxOpenCampaigns}
          hasOpenSpam={hasOpenSpam}
          openCountWithSpam={openCampaignsCountWithSpam}
          alertType={activeTab}
        />
      </div>
    </>
  )

  return (
    <>
      {isTemplatesDialogOpen && (
        <TemplateSelectionDialog
          setIsOpen={setIsTemplatesDialogOpen}
          codeScanningTemplates={codeScanningTemplates ?? templates}
          organizationLogin={organizationLogin}
          secretScanningTemplates={secretScanningTemplates ?? []}
          anyCampaigns={anyCampaigns}
          alertType={templateDialogType}
        />
      )}
      <Stack direction="horizontal" justify="space-between" align="center" gap="normal">
        <Heading as="h2" className="f2 text-normal">
          Campaigns
        </Heading>
        <Stack direction="horizontal" align="center" gap="condensed">
          <CampaignFeedbackLink alertType={activeTab} />
          {showCampaignCreationButton && (
            <CampaignCreationButton
              organizationLogin={organizationLogin}
              maxCampaignsReached={maxCampaignsReached}
              hasSpam={hasOpenSpam || hasDraftSpam}
              maxOpenCampaigns={maxOpenCampaigns}
              maxDraftCampaigns={maxDraftCampaigns}
              setIsTemplatesDialogOpen={setIsTemplatesDialogOpen}
              setTemplateDialogType={setTemplateDialogType}
            />
          )}
        </Stack>
      </Stack>
      <p className="fgColor-muted">Accelerate the remediation of alerts.</p>

      <UnderlinePanels aria-label="Campaign types">
        <UnderlinePanels.Tab
          icon={CodescanIcon}
          counter={codeCounts.openCampaignsCount}
          aria-selected={activeTab === 'code_scanning'}
          onSelect={() => setActiveTab('code_scanning')}
        >
          Code
        </UnderlinePanels.Tab>
        <UnderlinePanels.Tab
          icon={KeyIcon}
          counter={secretCounts.openCampaignsCount}
          aria-selected={activeTab === 'secret_scanning'}
          onSelect={() => setActiveTab('secret_scanning')}
        >
          Secrets
        </UnderlinePanels.Tab>

        <UnderlinePanels.Panel className="mt-2" hidden={activeTab !== 'code_scanning'}>
          {codeHasAny ? (
            CampaignsBody
          ) : (
            <NoCampaignsBlankSlate
              organizationLogin={organizationLogin}
              creationAllowed={showFullView}
              maxCampaignsReached={maxCampaignsReached}
              maxOpenCampaigns={maxOpenCampaigns}
              maxDraftCampaigns={maxDraftCampaigns}
              setIsTemplatesDialogOpen={setIsTemplatesDialogOpen}
              setTemplateDialogType={setTemplateDialogType}
              aboutCampaignsDocsUrl={aboutCampaignsDocsUrl}
              hasSpam={hasOpenSpam || hasDraftSpam}
              alertType="code_scanning"
              hasCodeScanningEnabled={codeScanningEnabled}
              hasSecretProtectionEnabled={secretProtectionEnabled}
            />
          )}
        </UnderlinePanels.Panel>
        <UnderlinePanels.Panel className="mt-2" hidden={activeTab !== 'secret_scanning'}>
          {secretHasAny ? (
            CampaignsBody
          ) : (
            <NoCampaignsBlankSlate
              organizationLogin={organizationLogin}
              creationAllowed={showFullView}
              maxCampaignsReached={maxCampaignsReached}
              maxOpenCampaigns={maxOpenCampaigns}
              maxDraftCampaigns={maxDraftCampaigns}
              setIsTemplatesDialogOpen={setIsTemplatesDialogOpen}
              setTemplateDialogType={setTemplateDialogType}
              aboutCampaignsDocsUrl={aboutCampaignsDocsUrl}
              hasSpam={hasOpenSpam || hasDraftSpam}
              alertType="secret_scanning"
              hasCodeScanningEnabled={codeScanningEnabled}
              hasSecretProtectionEnabled={secretProtectionEnabled}
            />
          )}
        </UnderlinePanels.Panel>
      </UnderlinePanels>
    </>
  )
}
