import type {ReactNode} from 'react'
import {Banner} from '@primer/react'
import type {AgenticAutofixError} from '../types/agentic-autofix-error'
import {rulesetsPath} from '@github-ui/paths'

export type AgenticAutofixErrorBannerProps = {
  error: AgenticAutofixError
  repository: {owner: string; name: string}
  onRetry: () => void
  onDismiss: () => void
}

export function AgenticAutofixErrorBanner({error, repository, onRetry, onDismiss}: AgenticAutofixErrorBannerProps) {
  let description = <>{error.message}</>
  let primaryAction: ReactNode | null = <Banner.PrimaryAction onClick={onRetry}>Retry</Banner.PrimaryAction>

  switch (error.errorType) {
    case 'customer_selection_required':
      description = (
        <>
          Before you can use agentic autofix, you need to pick a &quot;Usage billed to&quot; option in your Copilot
          settings.
        </>
      )
      primaryAction = (
        <Banner.PrimaryAction as="a" href="/settings/copilot/features" target="_blank">
          Settings
        </Banner.PrimaryAction>
      )
      break
    case 'repository_rules_violation':
      description = (
        <>
          Agentic autofix encountered an error and was unable to start working on the alert. This may be caused by a
          repository ruleset violation. See{' '}
          <a
            href="https://docs.github.com/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/creating-rulesets-for-a-repository#granting-bypass-permissions-for-your-branch-or-tag-ruleset"
            target="_blank"
            rel="noopener noreferrer"
          >
            granting bypass permissions for the agent
          </a>
          .
        </>
      )
      primaryAction = (
        <Banner.PrimaryAction
          as="a"
          href={rulesetsPath({owner: repository.owner, repo: repository.name})}
          target="_blank"
        >
          Manage rulesets
        </Banner.PrimaryAction>
      )
      break
    case 'max_queued_jobs_exceeded':
      description = (
        <>
          Agentic autofix encountered an error and was unable to start working on the alert. You have exceeded the
          maximum number of queued jobs. Please try again later.
        </>
      )
      break
    case 'cca_disabled':
      description = (
        <>
          Agentic autofix could not be started because Copilot cloud agent is not enabled for you or this repository.
          See{' '}
          <a
            href="https://docs.github.com/copilot/concepts/agents/cloud-agent/access-management"
            target="_blank"
            rel="noopener noreferrer"
          >
            Copilot cloud agent access management
          </a>{' '}
          for more information.
        </>
      )
      break
  }

  return (
    <Banner
      role="alert"
      variant="critical"
      title="Failed to assign to Copilot"
      hideTitle
      description={description}
      primaryAction={primaryAction}
      secondaryAction={<Banner.SecondaryAction onClick={onDismiss}>Dismiss</Banner.SecondaryAction>}
    />
  )
}
