import {useSharedDismissalMutation} from '../hooks/use-shared-dismissal-mutation'
import {BaseSharedDismissalDialog} from './BaseSharedDismissalDialog'
import {pluralizedTexts, type DismissalEntity} from '../utils/pluralized-texts'

export interface SharedDismissalDialogProps {
  setOpen: (open: boolean) => void
  alertNumbers: number[]
  path: string
  delegatedAlertDismissalEnabled: boolean
  entity: DismissalEntity
  prReviewThreadId?: number
  campaignNumber?: number
}

export function SharedDismissalDialog(props: SharedDismissalDialogProps) {
  const {setOpen, alertNumbers, path, delegatedAlertDismissalEnabled, entity, prReviewThreadId, campaignNumber} = props

  const {mutate, isPending, error} = useSharedDismissalMutation(path)

  const {title, subtitle, submitButtonLabel, delegatedAlertDismissal, reasons} = pluralizedTexts(
    entity,
    alertNumbers.length,
  )

  const dismissalOptions = [
    {value: 'FALSE_POSITIVE', label: 'False positive', description: reasons.falsePositiveDescription},
    {value: 'USED_IN_TESTS', label: 'Used in tests', description: reasons.usedInTestsDescription},
    {value: 'WONT_FIX', label: "Won't fix", description: reasons.wontFixDescription},
  ]

  const onSubmit = ({resolution, dismissalComment}: {resolution: string; dismissalComment: string}) => {
    mutate(
      {
        alertNumbers,
        resolution,
        dismissalComment,
        prReviewThreadId,
        campaignNumber,
      },
      {
        onSuccess: () => {
          setOpen(false)
          // Need to do a full page reload so that the sidebar numbers (which are not in react) get updated
          window.location.reload()
        },
      },
    )
  }

  return (
    <BaseSharedDismissalDialog
      setOpen={setOpen}
      count={alertNumbers.length}
      title={delegatedAlertDismissalEnabled ? delegatedAlertDismissal.title : title}
      subtitle={delegatedAlertDismissalEnabled ? delegatedAlertDismissal.subtitle : subtitle}
      submitButtonLabel={delegatedAlertDismissalEnabled ? delegatedAlertDismissal.submitButtonLabel : submitButtonLabel}
      dismissalOptions={dismissalOptions}
      error={error}
      isPending={isPending}
      onSubmit={onSubmit}
      delegatedAlertDismissalEnabled={delegatedAlertDismissalEnabled}
    />
  )
}
