import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {createAgenticAutofixErrorFromBody} from '@github-ui/code-scanning-shared/types/agentic-autofix-error'
import {fetchJson} from '../utils/fetch-json'
import {ApiError} from '../utils/api-error'

export type AssignToCopilotRequest = {
  alertNumbers: number[]
}

export type AssignToCopilotResponse = {
  message: string
  agenticAutofixJobId?: string
}

export function useAssignToCopilot(
  path: string,
): UseMutationResult<AssignToCopilotResponse, Error, AssignToCopilotRequest> {
  return useMutation({
    mutationFn: async request => {
      try {
        return await fetchJson(path, {
          method: 'post',
          body: {
            alert_numbers: request.alertNumbers,
          },
        })
      } catch (error) {
        if (error instanceof ApiError) {
          const agenticAutofixError = createAgenticAutofixErrorFromBody(error.responseBody)
          if (agenticAutofixError) {
            throw agenticAutofixError
          }
        }
        throw error
      }
    },
  })
}
