import {Stack} from '@primer/react'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {useStableRandom} from '@github-ui/use-stable-random'

export function RowLoading(): React.ReactElement {
  const width1 = `${useStableRandom({max: 21}) + 40}%`
  const width2 = `${useStableRandom({max: 21}) + 40}%`

  return (
    <Stack direction="horizontal" gap="condensed" className="tmp-px-3 py-2 border-bottom color-border-muted">
      <LoadingSkeleton variant="elliptical" height="md" width="md" />
      <Stack className="width-full">
        <LoadingSkeleton variant="rounded" height="sm" width={width1} />
        <LoadingSkeleton variant="rounded" height="12px" width={width2} className="mt-2" />
      </Stack>
    </Stack>
  )
}
