import {Breadcrumbs} from '@primer/react'
import type {AlertType} from '../types/security-campaign-alert'

export interface OrgSecurityCampaignBreadcrumbsProps {
  href: string
  text: string
  selectedText: string
  alertType: AlertType
}

export function OrgSecurityCampaignBreadcrumbs({
  href,
  text,
  selectedText,
  alertType,
}: OrgSecurityCampaignBreadcrumbsProps) {
  // Generate the alert type breadcrumb link with the appropriate query parameter
  const alertTypeHref = `${href}?alert_type=${alertType}`
  const alertTypeText = alertType === 'secret_scanning' ? 'Secrets' : 'Code'

  return (
    <Breadcrumbs className="mb-2">
      <Breadcrumbs.Item href={href}>{text}</Breadcrumbs.Item>
      <Breadcrumbs.Item href={alertTypeHref}>{alertTypeText}</Breadcrumbs.Item>
      <Breadcrumbs.Item selected>{selectedText}</Breadcrumbs.Item>
    </Breadcrumbs>
  )
}
