export class MetadataPresenceFilterProvider extends HasFilterProvider {
  constructor(metadataPresenceFiltersEnabled: boolean, options?: SuppliedFilterProviderOptions) {
    const metadataPresenceFilterValues = [
      {value: 'owner-email', displayName: 'Owner email', priority: 1},
      {value: 'owner-id', displayName: 'Owner ID', priority: 2},
      {value: 'owner-name', displayName: 'Owner name', priority: 3},
      {value: 'secret-id', displayName: 'Secret ID', priority: 4},
      {value: 'secret-name', displayName: 'Secret name', priority: 5},
      {value: 'secret-issued-date', displayName: 'Secret issued date', priority: 6},
      {value: 'secret-expiration-date', displayName: 'Secret expiration date', priority: 7},
      {value: 'organization-name', displayName: 'Organization name', priority: 8},
      {value: 'organization-id', displayName: 'Organization ID', priority: 9},
      {value: 'last-used-date', displayName: 'Last used date', priority: 10},
    ]

    const assigneeFilterValue = [{value: 'assignee', displayName: 'Assignee', priority: 1}]

    const filterValues = [...assigneeFilterValue]
    if (metadataPresenceFiltersEnabled) {
      filterValues.push(...metadataPresenceFilterValues)
    }

    const presenceOptions = {
      ...options,
      filterTypes: {
        exclusive: false,
        valueless: false,
        hasValue: false,
        multiValue: true,
        ...options?.filterTypes,
      },
    }
    super(filterValues, presenceOptions)
  }
}

