export class AutofixFilterProvider extends SelectFilterProvider {
  constructor(showNewFilters: boolean, options?: SuppliedFilterProviderOptions) {
    const filterKeys = {
      displayName: 'Autofix',
      key: 'autofix',
      priority: 1,
      icon: CopilotIcon,
      description: 'Filter by compatibility with Copilot Autofix',
    }
    const filterValues = [{value: 'supported', displayName: 'Supported', priority: 1}]

    if (showNewFilters) {
      filterValues.push({
        value: 'generated',
        displayName: 'Generated',
        priority: 2,
      })
      filterValues.push({
        value: 'accepted',
        displayName: 'Accepted',
        priority: 3,
      })
    }

    const opts = {
      ...options,
      filterTypes: {
        ...DEFAULT_FILTER_TYPE_OPTIONS,
        ...options?.filterTypes,
      },
    }

    super(filterKeys, filterValues, opts)
  }
}

