import type {LinkedBranch} from './linked-branch'
import type {LinkedPullRequest} from './linked-pull-request'
import type {Assignee} from './assignee'
import type {Repository} from './repository'
import type {RuleSeverity} from '@github-ui/code-scanning-shared/types/rule-severity'
import type {SecuritySeverity} from './security-severity'
import type {TrackingLink} from '@github-ui/code-scanning-shared/types/tracking-link'

export type SecurityCampaignAlert = {
  number: number
  alertType: AlertType
  title: string
  ruleSeverity: RuleSeverity
  securitySeverity: SecuritySeverity | null
  toolName: string
  truncatedPath: string
  startLine: number
  createdAt: string
  isFixed: boolean
  isDismissed: boolean
  fixedAt: string | null
  dismissedAt: string | null
  resolution: string
  hasSuggestedFix?: boolean
  repository: Repository
  assignees?: Assignee[]
  linkedPullRequests?: LinkedPullRequest[]
  linkedBranches?: LinkedBranch[]
  publiclyLeaked?: boolean
  multiRepo?: boolean
  validityActive?: boolean
  slug?: string // For secret scanning alerts
  rawSecret?: string | null // For secret scanning alerts
  trackingLinks?: TrackingLink[]
}

export type AlertParentLink =
  | {
      kind: 'repository'
    }
  | {
      kind: 'campaign'
      campaignNumber: number
    }

export type AlertType = 'code_scanning' | 'secret_scanning'

export const getAlertTypeFromSearchParams = (params: URLSearchParams): AlertType => {
  const alertType = params.get('alert_type')
  if (alertType === 'secret_scanning') {
    return 'secret_scanning'
  }
  return 'code_scanning'
}
